/// <summary>
///     Extension class for SalesTable2LineField
/// </summary>
[ExtensionOf(classStr(SalesTable2LineField))]
final class AVASalesTable2LineField_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>initFieldId</c> method.
///     AVA - Schneider 02.05.2024
/// </summary>
/// <param name="_tableId">
///     <c>TableId</c> as type
/// </param>
/// <param name="_fieldId">
///     <c>FieldId</c> as type
/// </param>
protected void initFieldId( TableId _tableId,
                            FieldId _fieldId    )
{
    next initFieldId(   _tableId,   
                        _fieldId);

    if(_tableId == tableNum(SalesTable))
    {
        if(     _fieldId    == fieldNum(SalesTable, DlvMode)
            ||  _fieldId    == fieldNum(SalesTable, DlvTerm)    
            ||  _fieldId    == fieldNum(SalesTable, DefaultDimension)
            ||  _fieldId    == fieldNum(SalesTable, InventLocationId)   )
        {
            this.checkSetUpdateSalesLine();
        }           
    }
}

/// <summary>
///     AVA <c>checkSetUpdateSalesLine</c> method.
///     AVA - Schneider 02.05.2024
/// </summary>
private void checkSetUpdateSalesLine()
{
    if(this.table2LineUpdate() == TradeTable2LineUpdate::Prompt)
    {
        this.updateSalesLines(NoYes::Yes);            
    }    
}
